using System;
using System.Linq;
using System.Reflection;
using HarmonyLib;
using RimWorld;
using Verse;
using RimWorld.Planet;

namespace ThornWhip
{
    // Map-generation only; no GameComponentTick or MapComponentTick.
    // Conservatively AUGMENTS a base that is already generated by the game or another
    // settlement mod. Buildings and pre-existing terrain are not destroyed.
    public static class ThornFortressGeneration
    {
        private static bool attempted;
        public static void Install(Harmony harmony)
        {
            if(attempted)return;attempted=true;
            try
            {
                // Postfix on MapGenerator.GenerateMap: applies to surface + Odyssey orbital maps.
                // Patch exactly one map-producing overload to avoid collisions and duplicate fortifications.
                MethodInfo generator=typeof(MapGenerator).GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic)
                    .FirstOrDefault(m=>m.Name=="GenerateMap" && m.ReturnType==typeof(Map));
                if(generator==null){Log.Warning("[ThornCorps] MapGenerator hook unavailable; fortress layouts disabled");return;}
                harmony.Patch(generator,postfix:new HarmonyMethod(typeof(ThornFortressGeneration),nameof(MapGenerated)));
            }
            catch(Exception ex){Log.Warning("[ThornCorps] fortress layout hook disabled: "+ex.Message);}
        }
        public static void MapGenerated(Map __result)
        {
            Map map=__result;
            if(map?.ParentFaction?.def?.defName!="TC_ThornCorps")return;
            try{Build(map);}catch(Exception ex){Log.Error("[ThornCorps] fortress build failed: "+ex);}
        }
        private static void Build(Map map)
        {
            // Orbital worlds are generated by Odyssey, then decorated with factory defenses.
            // Orbital vacuum cells are NEVER filled in with floor or structures.
            bool orbital=map.Parent?.def?.defName=="SpaceSettlement" ||
                map.Biome?.defName=="Space" || map.Parent?.def?.defName?.Contains("Space")==true;
            int width=Math.Min(orbital?42:66,map.Size.x-18),height=Math.Min(orbital?34:54,map.Size.z-18);
            if(width<22 || height<18)return;
            // Build a complete industrial wing on a contiguous empty plot instead of
            // scribbling independent wall segments over an already-generated settlement.
            IntVec3 mid=FindFortressPlot(map,width,height,orbital);
            if(!mid.IsValid)
            {
                Log.Warning("[ThornCorps] no safe plot for a coherent industrial fortress annex; vanilla base left untouched");
                return;
            }
            int west=mid.x-width/2,east=mid.x+width/2,south=mid.z-height/2,north=mid.z+height/2;
            ThingDef wall=DefDatabase<ThingDef>.GetNamedSilentFail("TC_Fort_ReinforcedWall") ?? DefDatabase<ThingDef>.GetNamedSilentFail("Wall");
            if(wall==null)return;
            ThingDef stuff=DefDatabase<ThingDef>.GetNamedSilentFail(orbital?"Plasteel":"Steel") ?? ThingDefOf.Steel;
            // A coherent defensive perimeter must not become random red bars across
            // vanilla base buildings. Choose an empty perimeter or leave vanilla intact.
            bool ringClear = true;
            for (int t=0;t<2 && ringClear;t++)
            {
                for(int x=west+t;x<=east-t;x++)
                    if(Math.Abs(x-mid.x)>3 && (!Clear(map,new IntVec3(x,0,south+t),orbital) || !Clear(map,new IntVec3(x,0,north-t),orbital)))
                    {ringClear=false;break;}
                for(int z=south+t;z<=north-t && ringClear;z++)
                    if(Math.Abs(z-mid.z)>3 && (!Clear(map,new IntVec3(west+t,0,z),orbital) || !Clear(map,new IntVec3(east-t,0,z),orbital)))
                    {ringClear=false;break;}
            }
            if(!ringClear)
            {
                Log.Warning("[ThornCorps] coherent fortress perimeter unavailable on this generated map; skipping fragmented ring");
                return;
            }
            for(int t=0;t<2;t++)
            {
                for(int x=west+t;x<=east-t;x++)
                {
                    if(Math.Abs(x-mid.x)>3)
                    {TryWall(map,new IntVec3(x,0,south+t),wall,stuff,orbital);
                     TryWall(map,new IntVec3(x,0,north-t),wall,stuff,orbital);}
                }
                for(int z=south+t;z<=north-t;z++)
                {
                    if(Math.Abs(z-mid.z)>3)
                    {TryWall(map,new IntVec3(west+t,0,z),wall,stuff,orbital);
                     TryWall(map,new IntVec3(east-t,0,z),wall,stuff,orbital);}
                }
            }
            // Four gate bastions: CE-compatible hard cover, not a bespoke combat system.
            ThingDef cover = DefDatabase<ThingDef>.GetNamedSilentFail("TC_Fort_Sandbag") ?? DefDatabase<ThingDef>.GetNamedSilentFail("Barricade");
            if (cover != null)
            {
                for (int step = -5; step <= 5; step++)
                {
                    if (Math.Abs(step) <= 2) continue; // 5-tile shooting/access lane
                    TryCover(map, new IntVec3(mid.x+step,0,south+4), cover, stuff, orbital);
                    TryCover(map, new IntVec3(mid.x+step,0,north-4), cover, stuff, orbital);
                    TryCover(map, new IntVec3(west+4,0,mid.z+step), cover, stuff, orbital);
                    TryCover(map, new IntVec3(east-4,0,mid.z+step), cover, stuff, orbital);
                }
            }
            // Industrial halls with firebreak corridors and distinct assembly / R&D benches.
            // Do not replace pre-existing pawn beds, structures or items.
            int sz=orbital?10:14;
            PlantWorkshop(map,new IntVec3(mid.x-sz,0,mid.z-10),wall,stuff,orbital,"TT_FactoryTable");
            PlantWorkshop(map,new IntVec3(mid.x+sz,0,mid.z+10),wall,stuff,orbital,"TT_DesignTable");
            PlantWorkshop(map,new IntVec3(mid.x+sz,0,mid.z-10),wall,stuff,orbital,"FabricationBench");
            PlantWorkshop(map,new IntVec3(mid.x-sz,0,mid.z+10),wall,stuff,orbital,"ElectricSmelter");
            InstallDefenseLine(map,mid,width,height,orbital);

        }
        private static IntVec3 FindFortressPlot(Map map,int width,int height,bool orbital)
        {
            // Off-center wings are favored so existing vanilla faction halls survive.
            // Work runs once at map-generation, not each tick.
            var center=map.Center;
            int[][] offsets = {
                new[]{width+6,0},new[]{-width-6,0},new[]{0,height+6},new[]{0,-height-6},
                new[]{width/2+13,height/2+13},new[]{-width/2-13,height/2+13},
                new[]{width/2+13,-height/2-13},new[]{-width/2-13,-height/2-13},
                new[]{0,0}
            };
            foreach(var off in offsets)
            {
                IntVec3 spot=new IntVec3(center.x+off[0],0,center.z+off[1]);
                bool clear=true;
                for(int t=0;t<2 && clear;t++)
                {
                    for(int x=spot.x-width/2+t;x<=spot.x+width/2-t && clear;x++)
                    {
                        if(System.Math.Abs(x-spot.x)<=3)continue;
                        clear=Clear(map,new IntVec3(x,0,spot.z-height/2+t),orbital) &&
                            Clear(map,new IntVec3(x,0,spot.z+height/2-t),orbital);
                    }
                    for(int z=spot.z-height/2+t;z<=spot.z+height/2-t && clear;z++)
                    {
                        if(System.Math.Abs(z-spot.z)<=3)continue;
                        clear=Clear(map,new IntVec3(spot.x-width/2+t,0,z),orbital) &&
                            Clear(map,new IntVec3(spot.x+width/2-t,0,z),orbital);
                    }
                }
                if(!clear)continue;
                int sz=orbital?10:14;
                foreach(var test in new[]{new IntVec3(spot.x-sz,0,spot.z-10),new IntVec3(spot.x+sz,0,spot.z+10),
                      new IntVec3(spot.x+sz,0,spot.z-10),new IntVec3(spot.x-sz,0,spot.z+10)})
                    if(!Clear(map,test,orbital))clear=false;
                if(clear)return spot;
            }
            return IntVec3.Invalid;
        }
        private static bool Clear(Map map,IntVec3 cell,bool orbit)
        {
            if(!cell.InBounds(map)||!cell.Standable(map))return false;
            if(orbit)
            {
                var terrain=cell.GetTerrain(map);
                string name=terrain?.defName??"";
                if(name.IndexOf("space",StringComparison.OrdinalIgnoreCase)>=0 ||
                   name.IndexOf("vacuum",StringComparison.OrdinalIgnoreCase)>=0)return false;
            }
            return !map.thingGrid.ThingsListAtFast(cell).Any(t=>t.def.category==ThingCategory.Building || t.def.category==ThingCategory.Item || t is Pawn);
        }
        private static void TryWall(Map map,IntVec3 at,ThingDef wall,ThingDef stuff,bool orbit)
        {
            if(!Clear(map,at,orbit))return;
            try{GenSpawn.Spawn(ThingMaker.MakeThing(wall,wall.MadeFromStuff?stuff:null),at,map,WipeMode.Vanish);}
            catch(Exception){} // if a custom map forbids walls, leave existing map intact
        }
        private static void TryCover(Map map,IntVec3 cell, ThingDef cover, ThingDef stuff,bool orbit)
        {
            if(!Clear(map,cell,orbit))return;
            try{GenSpawn.Spawn(ThingMaker.MakeThing(cover,cover.MadeFromStuff?stuff:null),cell,map,WipeMode.Vanish);}
            catch(Exception){} // A different map generator or CE may disallow this cell.
        }
        private static void InstallDefenseLine(Map map,IntVec3 mid,int width,int height,bool orbital)
        {
            int dx=width/2-8,dz=height/2-7;
            // Defense silhouettes and ammo variants are defined by our own CE ThingDefs.
            // Faction placement only; players may build the baseline turrets separately.
            string[] line={"Holder","Holder","Minigun","Minigun","Laser","Blaster","Railgun","ATGM","MLRS"};
            IntVec3[] positions={
              new IntVec3(mid.x-dx,0,mid.z-dz),new IntVec3(mid.x+dx,0,mid.z+dz),
              new IntVec3(mid.x-dx,0,mid.z+dz),new IntVec3(mid.x+dx,0,mid.z-dz),
              new IntVec3(mid.x,0,mid.z+dz),new IntVec3(mid.x,0,mid.z-dz),
              new IntVec3(mid.x+dx,0,mid.z),new IntVec3(mid.x-dx,0,mid.z),
              new IntVec3(mid.x+dx/2,0,mid.z-dz)
            };
            for(int i=0;i<line.Length;i++)
            {
                string name="TC_Turret_"+line[i];
                ThingDef def=DefDatabase<ThingDef>.GetNamedSilentFail(name);
                if(def==null)continue;
                var pos=positions[i];
                if(!FootprintClear(map,pos,def,orbital))continue;
                try
                {
                    Thing turret=ThingMaker.MakeThing(def);
                    turret.SetFaction(map.ParentFaction);
                    GenSpawn.Spawn(turret,pos,map,WipeMode.Vanish);
                    if(line[i]=="Holder")ConfigureSmallTurret(turret,i);
                }
                catch(Exception e){Log.Warning("[ThornCorps] turret fortress layout: "+e.Message);}
            }
            if(!orbital)
            {
                ThingDef embrasure=DefDatabase<ThingDef>.GetNamedSilentFail("TC_Fort_Embrasure");
                ThingDef trench=DefDatabase<ThingDef>.GetNamedSilentFail("TC_Trench_2");
                for(int side=-1;side<=1;side+=2)
                {
                    for(int off=-4;off<=4;off++)
                    {
                        if(Math.Abs(off)<=1)continue;
                        IntVec3 at=new IntVec3(mid.x+off,0,mid.z+side*(height/2-5));
                        if(embrasure!=null && Clear(map,at,false))TryFort(map,at,embrasure);
                        IntVec3 outer=new IntVec3(mid.x+off,0,mid.z+side*(height/2+2));
                        if(trench!=null && Clear(map,outer,false))TryFort(map,outer,trench);
                    }
                }
            }
        }
        private static bool FootprintClear(Map map,IntVec3 pos,ThingDef def,bool orbital)
        {
            for(int dx=0;dx<def.size.x;dx++)
            for(int dz=0;dz<def.size.z;dz++)
                if(!Clear(map,new IntVec3(pos.x+dx,0,pos.z+dz),orbital))return false;
            return true;
        }
        private static void ConfigureSmallTurret(Thing turret,int index)
        {
            var comp=turret.TryGetComp<CompThornTurret>();
            if(comp==null)return;
            string prefix=index==0?"TT_Auto_":"TT_Rifle_";
            ThingDef gun=DefDatabase<ThingDef>.AllDefsListForReading.FirstOrDefault(
                t=>t.defName.StartsWith(prefix,StringComparison.Ordinal) && t.IsWeapon);
            if(gun==null)return;
            try
            {
                var actual=ThingMaker.MakeThing(gun) as ThingWithComps;
                if(actual == null)return;
                var design=actual.TryGetComp<CompWeaponDesign>();
                if(design!=null)
                {
                    var bp=WeaponBlueprint.BasicFor(gun);
                    bp.Title="Корпус Терна / турельная сборка";
                    design.SetBlueprint(bp);
                }
                comp.MountFactoryWeapon(actual);
            }
            catch(Exception e){Log.Warning("[ThornCorps] faction holder armament: "+e.Message);}
        }
        private static void TryFort(Map map,IntVec3 cell,ThingDef fort)
        {
            if(!Clear(map,cell,false))return;
            try{GenSpawn.Spawn(ThingMaker.MakeThing(fort),cell,map,WipeMode.Vanish);}
            catch(Exception e){Log.Warning("[ThornCorps] fortification: "+e.Message);}
        }
        private static void PlantWorkshop(Map map,IntVec3 centre,ThingDef wall,ThingDef stuff,bool orbit,string benchName)
        {
            // Existing structures take priority. Do not obstruct orbital life-support or entrances.
            int halfX=6,halfZ=4;
            if(!Clear(map,centre,orbit))return;
            for(int dx=-halfX;dx<=halfX;dx++)
            for(int dz=-halfZ;dz<=halfZ;dz++)
            {
                if(Math.Abs(dx)!=halfX && Math.Abs(dz)!=halfZ)continue;
                // 3-wide opening to avoid trapping the defending garrison.
                if(dz==-halfZ && Math.Abs(dx)<=1)continue;
                TryWall(map,new IntVec3(centre.x+dx,0,centre.z+dz),wall,stuff,orbit);
            }
            if(!orbit)
            {
                var factoryFloor=DefDatabase<TerrainDef>.GetNamedSilentFail("Concrete");
                if(factoryFloor!=null)
                    for(int dx=-halfX+1;dx<halfX;dx++)
                    for(int dz=-halfZ+1;dz<halfZ;dz++)
                    {
                        var c=new IntVec3(centre.x+dx,0,centre.z+dz);
                        if(Clear(map,c,false) || (dx==0 && dz==0))
                            map.terrainGrid.SetTerrain(c,factoryFloor);
                    }
            }
            var bench=DefDatabase<ThingDef>.GetNamedSilentFail(benchName);
            var pos=new IntVec3(centre.x,0,centre.z);
            if(bench==null || !Clear(map,pos,orbit))return;
            try
            {
                Thing station=ThingMaker.MakeThing(bench);
                station.SetFaction(map.ParentFaction);
                GenSpawn.Spawn(station,pos,map,WipeMode.Vanish);
            }
            catch(Exception ex){Log.Warning("[ThornCorps] workshop "+benchName+" not placed: "+ex.Message);}
        }
    }
}
